SELECT EXISTS (
    SELECT 1 FROM TB_CLM WHERE CONTRACT_NO = #{contractNo}
       AND CLM_STAT_CD IN #{s})

SELECT COALESCE(SUM(I.PAY_AMT), 0)
  FROM TB_CLM C JOIN TB_CLM_CVRG I ON I.CLM_NO = C.CLM_NO
 WHERE C.CONTRACT_NO = #{contractNo} AND C.CLM_STAT_CD = '40' AND I.CVRG_CD = #{cvrgCd} AND C.CLM_NO <> #{excludeClmNo}

mapper.update:
UPDATE TB_CLM
   SET CLM_STAT_CD = #{clmStatCd}, TOTAL_PAY_AMT = #{totalPayAmt}, ADJ_EMP_ID = #{adjEmpId}, ADJ_DT = #{adjDt},
       DECIDE_EMP_ID = #{decideEmpId}, DECIDE_DT = #{decideDt}, DECIDE_MEMO = #{decideMemo}
 WHERE CLM_NO = #{clmNo}

UPDATE TB_CLM_CVRG
   SET ASSESSED_AMT = #{item.assessedAmt}, DEDUCTIBLE_AMT = #{item.deductibleAmt}, PAY_AMT = #{item.payAmt}
 WHERE CLM_NO = #{clmNo} AND CVRG_CD = #{item.cvrgCd}
